def populate_initial_officer_assignments(apps, schema_editor):
    UserProfile = apps.get_model('core', 'UserProfile')
    OfficerAssignment = apps.get_model('core', 'OfficerAssignment')
    District = apps.get_model('core', 'District')
    Taluk = apps.get_model('core', 'Taluk')
    RevenueVillage = apps.get_model('core', 'RevenueVillage')
    Firka = apps.get_model('core', 'Firka')

    for profile in UserProfile.objects.select_related('user').all():
        dist_obj = None
        taluk_obj = None
        vil_obj = None
        firka_obj = None

        if profile.district:
            dist_obj = District.objects.filter(name_en__iexact=profile.district.strip()).first()
        if dist_obj and profile.taluk:
            taluk_obj = Taluk.objects.filter(district=dist_obj, name_en__iexact=profile.taluk.strip()).first()
        if taluk_obj and profile.village:
            vil_obj = RevenueVillage.objects.filter(taluk=taluk_obj, name_en__iexact=profile.village.strip()).first()
            if vil_obj and vil_obj.firka:
                firka_obj = vil_obj.firka

        OfficerAssignment.objects.update_or_create(
            user=profile.user,
            role=profile.role,
            defaults={
                'district': dist_obj,
                'taluk': taluk_obj,
                'village': vil_obj,
                'firka': firka_obj,
                'designation': profile.role.replace('_', ' ').title(),
                'is_active': True,
                'is_additional_charge': False,
            }
        )


