        ('TAHSILDAR', 'RECLASSIFY_STRUCTURE', False, 'Inspector spot-verification required - UNVERIFIED'),
        
        # Collector authorities
        ('COLLECTOR', 'PASS_SECTION_6_ORDER', True, 'District Magistrate statutory powers - UNVERIFIED pending legal review'),
        ('COLLECTOR', 'ISSUE_SECTION_6_WARRANT', True, 'Eviction Warrant Execution - UNVERIFIED pending legal review'),

        # Revenue Inspector authorities
        ('INSPECTOR', 'RECORD_SERVICE_7', True, 'Process Server / Revenue Inspector service - UNVERIFIED pending legal review'),
